def pw(n, force, what, beside):
    return (f"Describe paragraph {n} as {FW[force]}: {what}. "
            f"It applies to courses at both awards the statement covers, the honours degree (FHEQ Level 6) and the master's (FHEQ Level 7), and is a duty on the course, not an outcome a student demonstrates. "
            f"Cite it as {CITE(n)} and do not call it a regulatory or legal requirement in its own right. "
            f"Set it beside {beside}.")

def pd(n, when, q):
    return (f"Raise paragraph {n} with a programme team or teacher when {when}, framing it as something the course is expected to do. "
            f"Ask: {q} "
            f"Do not put it to a student as a target they have to meet, and summarise it rather than reading the issuer's wording aloud.")

PROV = dict(type='expectation', rung='none', level='none', addressee='provider', domain='none', award=BOTH)
def sp(i, force, verbs, about, appliesTo, para, prac, reason, what, beside, when, q, **k):
    d = dict(PROV); d.update(k)
    s(i, force=force, verbs=verbs, about=about, appliesTo=appliesTo, para=para, prac=prac, ben=('n/a', reason),
      aaw=pw(i, force, what, beside), aad=pd(i, when, q), **d)

DUTY = 'a duty on the course or provider; the student meets its effect, not a standard to reach'

