# ---------------------------------------------------------------- section 4: the minimum standards (threshold rung)
def lw(k, name, award, others, fids):
    if award == HON:
        lvl = 'FHEQ Level 6 and FQHEIS Level 10 (spine:6)'; par = '4.6'
        tail = f"the honours descriptor items {fids} and the third-class column of Annex D (qaa/fheq-2024/annex-d/summary/r1/3rd)"
        notl = "the typical standard of an honours graduate, or the master's minimum"
        aw = 'an honours degree in architecture'
    else:
        lvl = 'FHEQ Level 7 and FQHEIS Level 11 (spine:7)'; par = '4.7'
        tail = f"the master's descriptor items {fids}"
        notl = "the typical standard of a master's graduate, or the honours minimum"
        aw = "a master's in architecture, including the integrated master's"
    return (f"Present this as the minimum the statement sets for {name} at the end of {aw}: a threshold every graduate of the award will have reached, at {lvl}. "
            f"Cite it as (QAA, 2026, Architecture Subject Benchmark Statement, para {par}, literacy {k}). "
            f"Do not present it as an ARB or RIBA criterion or as {notl}. "
            f"Set it beside {others} and {tail}.")

def ld(name, topic, q, award):
    end = 'honours degree' if award == HON else "master's"
    return (f"Bring this up when a student asks what {name} asks of them by the end of the {end}, or when a team maps {topic} across the course. "
            f"Tell a student in plain words what they will be able to do at minimum; with staff, frame it as what every graduate of the award must be able to show. "
            f"Ask: {q} "
            f"Make clear it is the floor, not the mark of a strong result, and do not read the definition out word for word.")

LIT = dict(type='threshold', rung='threshold', force='threshold', addressee='learner')
def lit(i, k, award, name, verbs, about, domain, para, prac, ben, others, fids, topic, q):
    lvl = 'fheq:6' if award == HON else 'fheq:7'
    s(i, level=lvl, appliesTo=("graduates of the bachelor's degree with honours" if award == HON else "graduates of the master's degree"),
      award=award, verbs=verbs, about=about, domain=domain, para=para, prac=prac, ben=ben,
      aaw=lw(k, name, award, others, fids), aad=ld(name, topic, q, award), find=ITEM[i], **LIT)

